package com.techconsulting.lending.controller;
import com.techconsulting.lending.domain.User; import com.techconsulting.lending.repository.UserRepository; import com.techconsulting.lending.security.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") @RequiredArgsConstructor public class AuthController { private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt; public record Register(@NotBlank String username,@Email @NotBlank String email,@NotBlank @Pattern(regexp="[A-Za-z0-9]+") String lenderId,@Size(min=8) String password){} public record Login(@NotBlank String username,@NotBlank String password){} public record AuthResponse(String token,Long userId,String username){}
 @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) AuthResponse register(@Valid @RequestBody Register r){String lenderId=r.lenderId().trim().toUpperCase();if(users.existsByUsernameIgnoreCaseOrEmailIgnoreCase(r.username(),r.email()))throw new IllegalArgumentException("Username or email already exists");if(users.existsByLenderIdIgnoreCase(lenderId))throw new IllegalArgumentException("Lender ID is already registered");User u=new User();u.setUsername(r.username());u.setEmail(r.email());u.setLenderId(lenderId);u.setPasswordHash(encoder.encode(r.password()));u=users.save(u);return new AuthResponse(jwt.create(u.getId(),u.getUsername()),u.getId(),u.getUsername());}
 @PostMapping("/login") AuthResponse login(@RequestBody Login r){User u=users.findByUsernameIgnoreCase(r.username()).filter(x->encoder.matches(r.password(),x.getPasswordHash())).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));return new AuthResponse(jwt.create(u.getId(),u.getUsername()),u.getId(),u.getUsername());}
}
